  const rows = await findPaymentsForOrder(10);
  assert.equal(rows.length, 1);
  assert.equal(rows[0].amount_cents, 4200);
});

test('uncapturedTotalCents sums uncaptured payments', async () => {
  const total = await uncapturedTotalCents();
  assert.equal(total, 9900);
});

